// Boar charge: 4-state FSM (idle → windup → charging → stunned). Once the
// charge launches, direction is locked at windup completion. While in windup
// or charging, the standard melee state machine is forcibly held back to
// 'chase' so the boar isn't doing two attacks at once. No suspend signal —
// it overrides velocity/state in place.
//
// Goblin Chief bash also drives this state machine (tuned via data values),
// so all reads/writes go through `enemy.data.chargeMechanic`.

import { GRID } from '../../game/GameConfig.js';

// Near-death threshold shared with Enemy.getNearDeathBlinkColor (≤30% HP) so
// an enemy's blink and its behavioral desperation start on the same hit —
// opt-in per enemy via `nearDeathCooldownMultiplier` on this mechanic's data.
const NEAR_DEATH_HP_FRACTION = 0.3;

export const ChargeMechanic = {
  isEnabled(enemy) {
    return enemy.data.chargeMechanic?.enabled === true;
  },

  init(enemy) {
    const cfg = enemy.data.chargeMechanic;
    enemy.chargeTimer = cfg.initialDelay ?? 0.6;
    enemy.chargeWindupTimer = 0;
    enemy.chargeDurationTimer = 0;
    enemy.chargeDir = { x: 0, y: 0 };
    enemy.chargeState = 'idle';
    enemy.chargeStunTimer = 0;
    enemy.chargeHasHit = false;
    enemy.chargeLastDeflector = null;
  },

  update(enemy, ctx) {
    const cfg = enemy.data.chargeMechanic;
    if (!cfg?.enabled) return;
    const { deltaTime, distance, effectiveVisionLength, onScreen } = ctx;
    // Cornered enemies charge more often — a landslide gains momentum as it's
    // chipped away, it doesn't slow down. Applies at both cooldown sites
    // (abort below and natural completion) so every path out of a charge
    // pays the same desperate-cycle price.
    const cooldownMult = cfg.nearDeathCooldownMultiplier
      && enemy.hp <= enemy.maxHp * NEAR_DEATH_HP_FRACTION
      ? cfg.nearDeathCooldownMultiplier : 1;

    // Wet/goo block charging entirely — a soaked or slimed boar can't get
    // traction. Off-screen joins the same abort: charging is a continuous
    // dash, not a single precomputed landing point (unlike Leap), so it can
    // close the last stretch to the player between one off-screen frame and
    // the next — the windup was the player's only chance to see it coming,
    // so losing the frame mid-charge is just as unfair as losing it mid-windup.
    // Abort an in-progress windup/charge and pay the full cooldown.
    if ((enemy.isWet() || enemy.isGooey() || !onScreen)
        && (enemy.chargeState === 'windup' || enemy.chargeState === 'charging')) {
      enemy.chargeState = 'idle';
      enemy.chargeTimer = cfg.cooldown * cooldownMult;
    }

    if (enemy.chargeState === 'stunned') {
      enemy.chargeStunTimer -= deltaTime;
      enemy.targetVelocity.vx = 0;
      enemy.targetVelocity.vy = 0;
      enemy.velocity.vx = 0;
      enemy.velocity.vy = 0;
      if (enemy.chargeStunTimer <= 0) enemy.chargeState = 'idle';
    } else if (enemy.chargeState === 'windup') {
      enemy.chargeWindupTimer -= deltaTime;
      enemy.targetVelocity.vx = 0;
      enemy.targetVelocity.vy = 0;
      enemy.velocity.vx = 0;
      enemy.velocity.vy = 0;
      if (enemy.state === 'windup' || enemy.state === 'attack') {
        enemy.state = 'chase';
        enemy.windupTimer = 0;
      }
      if (enemy.chargeWindupTimer <= 0) {
        enemy.chargeState = 'charging';
        enemy.chargeDurationTimer = cfg.chargeDuration;
        enemy.chargeHasHit = false;
        const cdx = enemy.target.position.x - enemy.position.x;
        const cdy = enemy.target.position.y - enemy.position.y;
        const cdist = Math.sqrt(cdx * cdx + cdy * cdy) || 1;
        enemy.chargeDir = { x: cdx / cdist, y: cdy / cdist };
        // Burst directly to top speed — bypass the acceleration ramp so the
        // 0.5s charge actually covers ground rather than spending most of it
        // accelerating.
        enemy.velocity.vx = enemy.chargeDir.x * cfg.chargeSpeed;
        enemy.velocity.vy = enemy.chargeDir.y * cfg.chargeSpeed;
      }
    } else if (enemy.chargeState === 'charging') {
      enemy.chargeDurationTimer -= deltaTime;
      // Reflector interaction (Tortoise): rolling through a BoulderSystem
      // deflector triangle bends the charge off its elbow, same as a rolling
      // boulder (BoulderSystem.js update(), the edge-triggered pattern this
      // mirrors). chargeDir is a unit vector and deflectVelocity preserves
      // input magnitude, so the result is already unit-length.
      if (cfg.deflectable && enemy.game?.boulderSystem) {
        const cx = enemy.position.x + (enemy.width ?? GRID.CELL_SIZE) / 2;
        const cy = enemy.position.y + (enemy.height ?? GRID.CELL_SIZE) / 2;
        const deflector = enemy.game.boulderSystem.findDeflectorAt(cx, cy);
        if (deflector) {
          if (enemy.chargeLastDeflector !== deflector) {
            enemy.chargeLastDeflector = deflector;
            const out = enemy.game.boulderSystem.deflectVelocity(
              deflector.data.deflectorElbow, enemy.chargeDir.x, enemy.chargeDir.y);
            if (out) enemy.chargeDir = { x: out.vx, y: out.vy };
          }
        } else {
          enemy.chargeLastDeflector = null;
        }
      }
      enemy.targetVelocity.vx = enemy.chargeDir.x * cfg.chargeSpeed;
      enemy.targetVelocity.vy = enemy.chargeDir.y * cfg.chargeSpeed;
      if (enemy.state === 'windup' || enemy.state === 'attack') {
        enemy.state = 'chase';
        enemy.windupTimer = 0;
      }
      if (enemy.chargeDurationTimer <= 0) {
        enemy.chargeState = 'idle';
        enemy.chargeTimer = cfg.cooldown * cooldownMult;
      }
    } else {
      // idle — count down to next charge whenever a target is engaged
      const engaged = enemy.state !== 'idle' || enemy.aggroMemoryActive || enemy.enraged;
      if (engaged) enemy.chargeTimer -= deltaTime;
      // A shelled enemy is already mid-response (ShellFormMechanic owns that
      // window — for the Tortoise it ends in a shell launch). Starting an
      // autonomous windup from inside the shell would fight it.
      if (enemy.chargeTimer <= 0
          && distance < cfg.chargeRange
          && enemy.target
          && !enemy.isStunned()
          && !enemy.isFrozen()
          && !enemy.isWet()
          && !enemy.isGooey()
          && !enemy.inShellForm
          && onScreen
          && enemy.hasVision(enemy.position, enemy.target.position, effectiveVisionLength, { ignoreCone: true })) {
        enemy.chargeState = 'windup';
        enemy.chargeWindupTimer = cfg.chargeWindup;
        if (enemy.state === 'windup') {
          enemy.state = 'chase';
          enemy.windupTimer = 0;
        }
      }
    }
  }
};
